public static client void main(Args args)

{
    //define the new object for controller class
    FTDBookReportController controller;

    controller = new FTDBookReportController();

    //pass the caller args to the controller
    controller.parmArgs(args);

    //set the report name and report design to run
    controller.parmReportName(ssrsReportStr(FTDBookReport, PrecisionDesign1));

    //execute the report
    //ssrsDemoController.preRunModifyContract();
    controller.parmShowDialog(false);

    controller.startOperation();
}

/// <summary>
///
/// </summary>
protected void preRunModifyContract()
{
    super();
    //get the reference of the current contract object
    FTDBookReportContract   contract    = this.parmReportContract().parmRdpContract();
    FTDAuthorTable          author      = Args.record();

    contract.parmAuthorId(author.Id);
}
